
create or replace function pg_temp.dashboard_mutation_qa() returns jsonb language plpgsql as $qa$
declare owner_id uuid; customer uuid:=gen_random_uuid(); v_captain uuid:=gen_random_uuid(); staff uuid:=gen_random_uuid(); agent_user uuid:=gen_random_uuid(); agent uuid:=gen_random_uuid();
 topup_id uuid:=gen_random_uuid(); settle_id uuid:=gen_random_uuid(); payment_id uuid:=gen_random_uuid(); credit_id uuid:=gen_random_uuid(); activation_id uuid:=gen_random_uuid(); receipt_id uuid:=gen_random_uuid(); fav uuid:=gen_random_uuid();
 cap_phone text:='+964790'||lpad((floor(random()*10000000)::bigint)::text,7,'0'); staff_phone text:='+964791'||lpad((floor(random()*10000000)::bigint)::text,7,'0'); agent_phone text:='+964792'||lpad((floor(random()*10000000)::bigint)::text,7,'0');
 coupon text:='QA'||substr(replace(gen_random_uuid()::text,'-',''),1,16);
 results jsonb:='[]'; j jsonb; expiry timestamptz; got_error text; before_count integer; amount_before integer;
begin
 begin
 select a.user_id into strict owner_id from public.tkt_admins a join public.tkt_profiles p using(user_id) where not p.blocked limit 1;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 insert into auth.users(id,email,aud,role) values(customer,'qa-'||customer||'@taktooka.invalid','authenticated','authenticated'),(v_captain,'qa-'||v_captain||'@taktooka.invalid','authenticated','authenticated'),(staff,'staff.'||replace(staff_phone,'+','')||'@taktooka.internal','authenticated','authenticated'),(agent_user,'qa-'||agent_user||'@taktooka.invalid','authenticated','authenticated');
 insert into public.tkt_profiles(user_id,name,phone,captain) values(customer,'QA mutation customer', '+964793'||lpad((floor(random()*10000000)::bigint)::text,7,'0'),false),(v_captain,'QA mutation captain',cap_phone,true),(agent_user,'QA mutation exchange',agent_phone,false);
 insert into tkt_private.wallets(user_id,balance)values(customer,0),(v_captain,0);
 perform public.tkt_manage('topup',jsonb_build_object('user_id',customer,'id',topup_id,'amount',10000));
 results:=results||jsonb_build_object('test','wallet topup changes balance and ledger','passed',(select balance=10000 from tkt_private.wallets where user_id=customer) and (select count(*)=1 from tkt_private.ledger where id=topup_id));
 perform public.tkt_manage('topup',jsonb_build_object('user_id',customer,'id',topup_id,'amount',10000));
 results:=results||jsonb_build_object('test','same topup request is not repeated','passed',(select balance=10000 from tkt_private.wallets where user_id=customer));
 got_error:=null;begin perform public.tkt_manage('topup',jsonb_build_object('user_id',customer,'id',topup_id,'amount',500));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','reused topup request with changed amount rejected','passed',coalesce(got_error='REQUEST_CONFLICT',false),'observed',coalesce(got_error,'accepted'));
 got_error:=null;begin perform public.tkt_manage('topup',jsonb_build_object('user_id',v_captain,'id',topup_id,'amount',10000));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','reused topup request for different account rejected','passed',coalesce(got_error='REQUEST_CONFLICT',false));
 got_error:=null;begin perform public.tkt_manage('topup',jsonb_build_object('user_id',customer,'id',gen_random_uuid(),'amount',-1));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','negative topup rejected','passed',got_error='INVALID_AMOUNT');
 perform public.tkt_manage('topup',jsonb_build_object('user_id',v_captain,'id',gen_random_uuid(),'amount',15000));
 perform public.tkt_manage('settle',jsonb_build_object('user_id',v_captain,'id',settle_id,'amount',4000));
 results:=results||jsonb_build_object('test','captain settlement deducts balance and records debit','passed',(select balance=11000 from tkt_private.wallets where user_id=v_captain)and(select amount=-4000 from tkt_private.ledger where id=settle_id));
 perform public.tkt_manage('settle',jsonb_build_object('user_id',v_captain,'id',settle_id,'amount',4000));
 results:=results||jsonb_build_object('test','settlement duplicate not deducted twice','passed',(select balance=11000 from tkt_private.wallets where user_id=v_captain));
 got_error:=null;begin perform public.tkt_manage('settle',jsonb_build_object('user_id',v_captain,'id',settle_id,'amount',1000));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','reused settlement request with changed amount rejected','passed',coalesce(got_error='REQUEST_CONFLICT',false));
 got_error:=null;begin perform public.tkt_manage('settle',jsonb_build_object('user_id',v_captain,'id',gen_random_uuid(),'amount',12000));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','settlement above balance rejected','passed',got_error='INSUFFICIENT_BALANCE');
 got_error:=null;begin perform public.tkt_manage('settle',jsonb_build_object('user_id',customer,'id',gen_random_uuid(),'amount',1));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','customer cannot receive captain settlement','passed',got_error='CAPTAIN_REQUIRED');
 perform public.tkt_manage('role',jsonb_build_object('user_id',customer,'captain',true));
 results:=results||jsonb_build_object('test','activate captain role','passed',(select captain and not online from public.tkt_profiles where user_id=customer));
 perform public.tkt_manage('renew',jsonb_build_object('user_id',customer,'payment_id',payment_id));
 select expires_at into expiry from public.tkt_profiles where user_id=customer;
 results:=results||jsonb_build_object('test','renew adds seven days and one payment','passed',expiry=now()+interval '7 days' and (select count(*)=1 from public.tkt_payments where id=payment_id));
 perform public.tkt_manage('renew',jsonb_build_object('user_id',customer,'payment_id',payment_id));
 results:=results||jsonb_build_object('test','renew duplicate does not extend twice','passed',(select expires_at=expiry from public.tkt_profiles where user_id=customer));
 perform public.tkt_manage('subscription_edit',jsonb_build_object('user_id',customer,'expires_at',now()+interval '14 days'));
 results:=results||jsonb_build_object('test','edit subscription expiry','passed',(select expires_at=now()+interval '14 days' from public.tkt_profiles where user_id=customer));
 got_error:=null;begin perform public.tkt_manage('renew',jsonb_build_object('user_id',v_captain,'payment_id',payment_id));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','reused subscription payment for different captain rejected','passed',coalesce(got_error='REQUEST_CONFLICT',false));
 perform public.tkt_manage('role',jsonb_build_object('user_id',customer,'captain',false));
 results:=results||jsonb_build_object('test','revoke captain role','passed',(select not captain from public.tkt_profiles where user_id=customer));
 perform public.tkt_manage('block',jsonb_build_object('user_id',customer,'blocked',true));
 results:=results||jsonb_build_object('test','block account','passed',(select blocked and not online from public.tkt_profiles where user_id=customer));
 perform public.tkt_manage('block',jsonb_build_object('user_id',customer,'blocked',false));
 results:=results||jsonb_build_object('test','unblock account','passed',(select not blocked from public.tkt_profiles where user_id=customer));
 got_error:=null;begin perform public.tkt_manage('block',jsonb_build_object('user_id',owner_id,'blocked',true));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','owner account protected','passed',got_error='PROTECTED_ADMIN');
 perform public.tkt_manage('archive',jsonb_build_object('kind','user','entity_id',customer));
 results:=results||jsonb_build_object('test','archive blocks account and preserves record','passed',(select blocked from public.tkt_profiles where user_id=customer)and exists(select 1 from tkt_private.admin_archives where kind='user'and entity_id=customer::text));
 j:=public.tkt_manage('users',jsonb_build_object('search','QA mutation customer'));
 results:=results||jsonb_build_object('test','archived account hidden from normal list','passed',not exists(select 1 from jsonb_array_elements(j)x where x->>'user_id'=customer::text));
 perform public.tkt_manage('restore',jsonb_build_object('kind','user','entity_id',customer));
 results:=results||jsonb_build_object('test','restore preserves block until explicit unblock','passed',not exists(select 1 from tkt_private.admin_archives where kind='user'and entity_id=customer::text)and(select blocked from public.tkt_profiles where user_id=customer));
 perform public.tkt_manage('block',jsonb_build_object('user_id',customer,'blocked',false));
 insert into public.tkt_saved_places(id,user_id,label,lat,lng)values(fav,customer,'QA place',33.5,44.4);
 perform public.tkt_manage('favorite_edit',jsonb_build_object('id',fav,'label','QA edited','lat',33.6,'lng',44.5));
 results:=results||jsonb_build_object('test','edit favorite address','passed',(select label='QA edited' and lat=33.6 and lng=44.5 from public.tkt_saved_places where id=fav));
 perform public.tkt_manage('favorite_delete',jsonb_build_object('id',fav));
 results:=results||jsonb_build_object('test','delete favorite address','passed',not exists(select 1 from public.tkt_saved_places where id=fav));
 perform public.tkt_manage('coupon_admin',jsonb_build_object('code',coupon,'amount',1000,'expires_at',now()+interval '1 day','max_uses',1,'active',true,'reward_type','amount'));
 results:=results||jsonb_build_object('test','create test coupon','passed',exists(select 1 from tkt_private.coupons where code=upper(coupon)and amount=1000));
 perform public.tkt_manage('coupon_delete',jsonb_build_object('code',coupon));
 results:=results||jsonb_build_object('test','delete unused coupon','passed',not exists(select 1 from tkt_private.coupons where code=upper(coupon)));
 perform public.tkt_staff('attach',jsonb_build_object('user_id',staff,'phone',staff_phone,'name','QA mutation staff','permissions',jsonb_build_object('users',jsonb_build_object('view',true,'edit',false)),'active',true));
 results:=results||jsonb_build_object('test','create staff and attach permissions','passed',exists(select 1 from tkt_private.staff_accounts where user_id=staff and active));
 perform set_config('request.jwt.claim.sub',staff::text,true);
 j:=public.tkt_manage('users','{}');
 results:=results||jsonb_build_object('test','view-only staff can read users','passed',jsonb_typeof(j)='array');
 got_error:=null;begin perform public.tkt_manage('role',jsonb_build_object('user_id',customer,'captain',true));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','view-only staff cannot activate captain','passed',got_error='PERMISSION_DENIED');
 got_error:=null;begin perform public.tkt_manage('topup',jsonb_build_object('user_id',customer,'id',gen_random_uuid(),'amount',1));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','staff without finance cannot top up','passed',got_error='PERMISSION_DENIED');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.tkt_staff('update',jsonb_build_object('user_id',staff,'name','QA mutation staff','permissions',jsonb_build_object('users',jsonb_build_object('view',true,'edit',true)),'active',true));
 perform set_config('request.jwt.claim.sub',staff::text,true);
 perform public.tkt_manage('role',jsonb_build_object('user_id',customer,'captain',true));
 results:=results||jsonb_build_object('test','updated staff permission takes effect','passed',(select captain from public.tkt_profiles where user_id=customer));
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.tkt_staff('update',jsonb_build_object('user_id',staff,'name','QA mutation staff','permissions',jsonb_build_object('users',jsonb_build_object('view',true,'edit',true)),'active',false));
 perform set_config('request.jwt.claim.sub',staff::text,true);
 got_error:=null;begin perform public.tkt_manage('users','{}');exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','disabled staff denied access','passed',got_error='PERMISSION_DENIED');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 insert into tkt_private.exchange_agents(id,name,phone,pin_hash,balance,active,user_id)values(agent,'QA mutation agent',agent_phone,'qa-unusable-hash',0,true,agent_user);
 perform public.tkt_exchange('admin_credit',jsonb_build_object('agent_id',agent,'id',credit_id,'amount',10000));
 results:=results||jsonb_build_object('test','exchange credit changes balance','passed',(select balance=10000 from tkt_private.exchange_agents where id=agent));
 perform public.tkt_exchange('admin_credit',jsonb_build_object('agent_id',agent,'id',credit_id,'amount',10000));
 results:=results||jsonb_build_object('test','exchange duplicate credit not repeated','passed',(select balance=10000 from tkt_private.exchange_agents where id=agent));
 got_error:=null;begin perform public.tkt_exchange('admin_credit',jsonb_build_object('agent_id',agent,'id',credit_id,'amount',500));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','exchange credit conflicting request rejected','passed',got_error='REQUEST_CONFLICT');
 perform public.tkt_exchange('admin_toggle',jsonb_build_object('agent_id',agent,'active',false));
 results:=results||jsonb_build_object('test','disable exchange','passed',(select not active from tkt_private.exchange_agents where id=agent));
 perform public.tkt_exchange('admin_toggle',jsonb_build_object('agent_id',agent,'active',true));
 perform set_config('request.jwt.claim.sub',agent_user::text,true);
 j:=public.tkt_exchange('activate',jsonb_build_object('id',activation_id,'captain_id',v_captain,'phone',cap_phone,'weeks',1));
 results:=results||jsonb_build_object('test','exchange activation debits 5000 and adds seven days','passed',(select balance=5000 from tkt_private.exchange_agents where id=agent)and(select expires_at=now()+interval '7 days' from public.tkt_profiles where user_id=v_captain));
 perform public.tkt_exchange('activate',jsonb_build_object('id',activation_id,'captain_id',v_captain,'phone',cap_phone,'weeks',1));
 results:=results||jsonb_build_object('test','exchange activation duplicate not repeated','passed',(select balance=5000 from tkt_private.exchange_agents where id=agent)and(select expires_at=now()+interval '7 days' from public.tkt_profiles where user_id=v_captain));
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 j:=public.tkt_exchange('admin_settle',jsonb_build_object('agent_id',agent,'id',receipt_id,'amount',5000,'note','QA settlement'));
 results:=results||jsonb_build_object('test','exchange settlement clears debt','passed',(j->>'due_after')::integer=0 and (select balance=5000 from tkt_private.exchange_agents where id=agent));
 perform public.tkt_exchange('admin_settle',jsonb_build_object('agent_id',agent,'id',receipt_id,'amount',5000,'note','QA settlement'));
 results:=results||jsonb_build_object('test','exchange settlement duplicate not repeated','passed',(select count(*)=1 from tkt_private.exchange_settlements where id=receipt_id));
 got_error:=null;begin perform public.tkt_exchange('admin_settle',jsonb_build_object('agent_id',agent,'id',gen_random_uuid(),'amount',1,'note','QA'));exception when others then got_error:=sqlerrm;end;
 results:=results||jsonb_build_object('test','settlement above exchange debt rejected','passed',got_error='SETTLEMENT_EXCEEDS_DUE');
 raise exception using errcode='ZQ001',message='QA_ROLLBACK';
 exception when sqlstate 'ZQ001' then return jsonb_build_object('rolled_back',true,'checks',results,'fixture_users_remaining',(select count(*)from auth.users where id in(customer,v_captain,staff,agent_user)),'fixture_staff_remaining',(select count(*)from tkt_private.staff_accounts where user_id=staff));
 when others then return jsonb_build_object('rolled_back',true,'checks',results,'error',sqlerrm,'sqlstate',sqlstate);
 end;
end;
$qa$;
select pg_temp.dashboard_mutation_qa() as qa_result;
